// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // fuzz parameters: from address, v value, decimals, and a boolean to choose which callee to deploy
    function testFuzz_property(address from, uint256 v, uint256 decimals, bool useReverter) public {
        // keep decimals small to avoid overflow in multiplication, but allow wide domain
        decimals = bound(decimals, 0, 18);
        v = bound(v, 0, type(uint256).max / (10 ** decimals == 0 ? 1 : 10 ** decimals));

        // deploy adversarial callee that reverts with arbitrary data we control
        bytes memory sentinel = abi.encodePacked("UNIQUE_REVERT:");
        // two possible callees: one that reverts with custom data, another that does not revert
        Reverter rev = new Reverter(sentinel);
        NonReverter ok = new NonReverter();

        address callee = useReverter ? address(rev) : address(ok);

        // build single-recipient array to keep observation simple (one call made)
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);

        // call transfer and capture whether it reverts and the revert data
        bool okCall;
        bytes memory revertData;
        try c.transfer(from, callee, tos, v, decimals) {
            okCall = true;
            revertData = "";
        } catch (bytes memory reason) {
            okCall = false;
            revertData = reason;
        }

        // General rule: if we routed to the Reverter which always reverts with sentinel + caller addr,
        // the reference implementation should propagate THAT exact revert data. The mutant replaces it
        // with a fixed "external call failed" message, so for some inputs (when useReverter==true)
        // the propagated revert bytes differ from the callee's actual revert bytes. We assert the
        // reference preserves the callee's revert bytes for all inputs by comparing what we caught
        // from c.transfer to what the callee actually produced.

        // Observe the callee's recorded revert bytes via the helper's getter.
        if (useReverter) {
            // callee recorded what it reverted with (encoded in its lastRevertData getter)
            bytes memory calleeRevert = rev.lastRevertData();
            // The reference C should have propagated the exact revert bytes from callee, so
            // when c.transfer reverted (okCall==false), revertData must equal calleeRevert.
            // When c.transfer did not revert (okCall==true), that contradicts the callee always reverting,
            // so that is also a violation we want the mutant to trigger for some inputs (but reference never does).
            // Single assertion that the reference satisfies for all admissible inputs:
            assertTrue(!okCall && keccak256(revertData) == keccak256(calleeRevert));
        } else {
            // when using NonReverter, the call should succeed and produce no revert data
            assertTrue(okCall && revertData.length == 0);
        }
    }
}

// adversarial callee that always reverts with identifiable data and records the revert bytes
contract Reverter {
    bytes private _sentinel;
    bytes private _lastRevert;
    constructor(bytes memory sentinel) {
        _sentinel = sentinel;
    }
    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)")) and revert
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        // prepare unique revert payload that includes sentinel and caller address to ensure uniqueness
        bytes memory payload = abi.encodePacked(_sentinel, msg.sender, from, to, value);
        _lastRevert = payload;
        revert(string(payload));
    }
    // record last revert payload (as bytes)
    function lastRevertData() external view returns (bytes memory) {
        return _lastRevert;
    }
}

// adversarial callee that accepts the call and returns true
contract NonReverter {
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        return true;
    }
}
